package contract

func DeclarationDocs() map[string]string {
	return map[string]string{
		"":                "The project declaration `.cockpit/project.yaml`, read from the submitted commit. Paths are relative to the repository root.",
		"hostApi":         "The host API the scripts are written against. The hub refuses a value outside the set it serves, and the runner refuses one that differs from its own.",
		"project":         "The services of the stack.",
		"project.builder": "A service that runs in the build stage before `compose build`, alone on the outside network and binding only the run's build copy of the commit, for downloads that do not fit a Dockerfile.",
		"project.expectedServices": "The services the boot stage waits for: each must run and, when it has a healthcheck, be healthy. A one-shot service is ready when it exits 0. " +
			"Leave out services that start only under a profile.",
		"project.networkOnlyKeys":   "Accepted for compatibility; the hub does not read it.",
		"inputs":                    "Local inputs of a submit besides the commit.",
		"inputs.dirty":              "Paths whose uncommitted changes refuse a submit, so local edits are never silently left out. The run always reads the commit.",
		"inputs.runnerSources":      "Directories of the commit copied read-only into the runner at `/work/source/<name>`, for `ctx.readSource` and `ctx.listSource`.",
		"inputs.runnerSources.name": "The source name flows pass to `ctx.readSource` and `ctx.listSource`.",
		"inputs.runnerSources.path": "The directory in the commit.",
		"compose":                   "The compose file set of the run.",
		"compose.files":             "The compose files in order. The hub adds its harness file last, which removes every published `ports` entry of the consumer.",
		"compose.forbidden":         "Substrings no file name of the set may contain, so a file meant for local use never enters a sealed run.",
		"compose.projectDirectory":  "The directory compose resolves relative paths against; the repository root when omitted.",
		"ports":                     "Services published on `127.0.0.1` while the run's environment is up.",
		"ports.name":                "The edge name: collectors reach the port as `http://<name>/...`, `databases[].port` names it, and run.env carries `RUN_PORT_<NAME>`.",
		"ports.offset":              "The slot in the run's port block: the host port is the block base plus the offset, from 0 to 98. 99 is reserved for the seal probe.",
		"ports.service":             "The compose service behind the port.",
		"ports.port":                "The container port of that service.",
		"ports.display":             "The label the screen and the kit README show for the port.",
		"ports.open":                "How the port is offered: `browser` at `http://<run id>.localhost:<port>`, an origin of its own per run; `link` at `http://127.0.0.1:<port>`; `copy` as an address to copy, for a port that is not HTTP.",
		"images":                    "Content keys for built images, so a commit whose image inputs did not change reuses the image it built before.",
		"images.key":                "The run.env variable (`IMG_...`) holding the key. Use it in the image tag of a built service, such as `image: shop-api:${IMG_API}`, and the build stage skips an image that is present.",
		"images.inputs":             "The paths whose git object ids the key hashes, together with the compose files.",
		"env":                       "The credential generator, run once per run before compose starts.",
		"env.command":               "The argv. It runs with the extracted commit mounted writable at `/src` as the working directory, as the hub's user, under umask 077.",
		"env.image":                 "The image the command runs in, pinned by digest. It must have `/bin/sh`, and it runs with no network, a read-only root and no capabilities.",
		"env.outputs":               "The files the command writes. Each one is a value source of the run redactor. `.env` in the compose project directory becomes the env file of every compose call, and an output named `e2e.private.env.json` becomes the runner's private env.",
		"secrets":                   "The files whose values are credentials of the run.",
		"secrets.sources":           "Files of the run read as value sources of the run redactor, usually env outputs. At least one is required.",
		"secrets.sources.path":      "The file.",
		"secrets.sources.format":    "`dotenv` reads the value of each key, `json` every string leaf, `pem` each body line of its PEM blocks.",
		"secrets.publicNames":       "Dotenv keys or JSON field names whose values are not secret and stay readable.",
		"secrets.patterns":          "RE2 expressions; every match is masked in addition to the values of the sources.",
		"databases":                 "Databases collectors read through `ctx.sql`. The hub logs in as the root user only to create a read-only user for the run, and reads as that user.",
		"databases.name":            "The name collectors pass to `ctx.sql.query`.",
		"databases.driver":          "The database engine.",
		"databases.port":            "The `ports` name that publishes the database.",
		"databases.readSchemas":     "For PostgreSQL, the schemas of `database` the reader may select from; for MySQL, the databases.",
		"databases.ownerRole":       "PostgreSQL only: the role that creates tables after the collectors start, so the reader can also select from them.",
		"databases.rootSecret":      "A key of a `dotenv` source in `secrets.sources` that holds the root password.",
		"databases.rootUser":        "The user the hub logs in as to create the reader; `postgres` or `root` when omitted.",
		"databases.database":        "For PostgreSQL, the database to connect to (`postgres` when omitted); for MySQL, the default database for unqualified table names, which must be one of `readSchemas`.",
		"exec":                      "What collectors may run with `ctx.docker.exec`.",
		"exec.allow":                "Allowed argv prefixes. An exec passes when its argv starts with one of them, and the first element must be a program, not a shell.",
		"scripts":                   "Where the TypeScript scripts live.",
		"scripts.dir":               "The directory the runner sees as `/work/scripts`; `env.json` sits at its top.",
		"scripts.suites":            "The suites directory inside `dir`: each `<name>.ts` whose name is a suite name is a suite.",
		"scripts.collectors":        "The collectors directory inside `dir`: each `<id>.ts` is a collector. Without it the run has no collectors.",
		"kit":                       "The handoff text for a person using the run's environment.",
		"kit.notes":                 "Text added to the run's kit README, shown on the screen's Environment page and in `env/README.md`.",
	}
}
